create table loki.loki_ddl_logs (
    ddl_log_id                number default on null to_number(sys_guid(), 'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx') not null enable,
    ddl                       clob not null enable,
    schema_name               varchar2(255 byte) not null enable,
    object_name               varchar2(255 byte) not null enable,
    object_type               varchar2(255 byte) not null enable,
    event                     varchar2(20 byte) not null enable,
    logged                    timestamp(6) with local time zone default on null localtimestamp not null enable,
    logged_by_db_user         varchar2(255 byte) default on null user not null enable,
    logged_by_db_current_user varchar2(255 byte) default on null sys_context('userenv', 'current_user') not null enable,
    logged_by_db_proxy_user   varchar2(255 byte) default sys_context('userenv', 'proxy_user'),
    logged_by_apex_user       varchar2(255 byte) default sys_context('apex$session', 'app_user'),
    ddl_preview               varchar2(255 byte)
);

alter table loki.loki_ddl_logs
    add constraint loki_ddl_logs_pk primary key ( ddl_log_id )
        using index enable;


